SELECT b.id AS benefitId, b.benefit_no AS benefitNo, b.order_id AS orderId, o.order_no AS orderNo, b.product_id AS productId, b.store_id AS storeId, b.coach_id AS coachId, c.coach_name AS coachName, COALESCE(p.product_name, o.product_name) AS productName, p.cover_url AS coverUrl, p.service_type AS serviceType, p.duration_minutes AS durationMinutes, p.daily_lesson_limit AS dailyLessonLimit, COALESCE(s.storeName, sa.storeName) AS storeName, b.total_lessons AS totalLessons, b.used_lessons AS usedLessons, b.frozen_lessons AS frozenLessons, b.remaining_lessons AS remainingLessons, b.effective_at AS effectiveAt, b.expire_at AS expireAt, b.status AS status, b.created_at AS createdAt FROM pt_member_private_benefit b LEFT JOIN pt_private_order o ON o.id = b.order_id LEFT JOIN pt_product p ON p.id = b.product_id LEFT JOIN store_address sa ON sa.storeAddrId = b.store_id LEFT JOIN store s ON s.storeId = sa.storeId LEFT JOIN pt_coach c ON c.id = b.coach_id WHERE b.member_id = #{userId}
AND b.status = #{status}
ORDER BY (b.status = 1 AND (b.expire_at IS NULL OR b.expire_at > NOW())) DESC, b.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM pt_member_private_benefit b
WHERE b.member_id = #{userId}

    AND b.status = #{status}

mapper.update:
UPDATE pt_member_private_benefit
SET frozen_lessons = frozen_lessons + #{n},
    remaining_lessons = remaining_lessons - #{n}
WHERE id = #{id} AND status = 1 AND remaining_lessons >= #{n}

UPDATE pt_member_private_benefit
SET frozen_lessons = frozen_lessons - #{n},
    used_lessons = used_lessons + #{n}
WHERE id = #{id} AND frozen_lessons >= #{n}

UPDATE pt_member_private_benefit
SET frozen_lessons = frozen_lessons - #{n},
    remaining_lessons = remaining_lessons + #{n}
WHERE id = #{id} AND frozen_lessons >= #{n}

UPDATE pt_member_private_benefit
SET total_lessons = total_lessons - #{n},
    remaining_lessons = remaining_lessons - #{n}
WHERE id = #{id} AND remaining_lessons >= #{n}

